 $('#addPurchaseLine').onclick=()=>{read();if(lines.length<50)lines.push({item:'',specification:'',qty:1,unit:'',unit_price:''});render();};$('#addApprover').onclick=()=>{read();if(approvals.length<10)approvals.push({user_id:'',required:false});render();};render();
